    "rawRegion": "台灣",
    "regionKey": "TW",
    "regionLabel": "台灣",
    "message": "LCP就像是拳頭沒人要的小孩一樣，除了分潤最少、不聽隊伍的訴求等等不說。\n原本PCS、VCS、LJL分開運營的模式尚具活力，成立LCP以後名額只開8個，還因為莫名奇妙的平衡原則塞入實力遠低於其他隊伍的大洋洲隊伍，讓沒入選的原PCS隊伍自生自滅；到了2027年，才赫然發現現在模式不可行，要改回以前的模式，但贊助商、隊伍、選手已經走的走，消失的消失，環境永久受創，實在對拳頭失望透頂…"
