    "message": "重視不是靠口說的，是要用實質行動告訴給觀眾聽的。光是Frank Esports事件和LCP次級聯賽貧乏得跟鬼一樣，根本不需要再談甚麼重視了。把現在掌握話語權的BanChee趕下台，把新加坡草台班子趕下台，把賽區主導權重新交回到鍇睿手上，謝謝。"
