    "organization": "一名看了12年比賽的觀眾",
    "message": "前陣子將賽區合併導致台港澳賽區只剩3隻一級隊伍，其他戰隊成員被迫失業，現在又分回各打各的，我可以接受但你配套措施要快點出來，不能讓戰隊不敢投入，我們有很好的後勤團隊，你們能不能做點對賽區有益的事別再搞我們賽區了，還有那個產品總監感覺Fire掉，沒用的東西"
