    "regionLabel": "台灣",
    "organization": "觀眾/玩家",
    "message": "1.希望能放寬戰隊贊助商的審核，盡量讓願意出資的廠商都能夠順利贊助，以利更多企業支持此電競項目\n2.希望能夠嚴正審視賽制，不要每年都不一樣或是出現像2026第三賽段這種提前淘汰隊伍的賽制，第三賽段理應還在例行賽範圍內，不應該提前淘汰隊伍，要淘汰也是在季後賽"
