    "regionKey": "TW",
    "regionLabel": "台灣",
    "organization": "觀眾",
    "message": "我希望Riot對於賽區能有一個更爲永續可經營的長期政策，而非一直朝令夕改，並且正視有關新加坡團隊的經營問題，在S15粉絲曾經因為和總監討論有關bo3,bo5的問題，被總監嗆「你覺得這樣改能讓我們拿世界冠軍嗎？」可見其根本沒有在尊重即使成績爛也一直關注賽區的粉絲，並且當賽區打得好如去年進8強的CFO時，他也第一個跳出來沾光，但實際上他對於CFO一直都沒有幫助，甚至在今年Junjia和HongQ兩位強力選手的出手他也沒有幫助留下。我認為Riot需要對於LCP賽區提出一個可持續性的政策並且安排會做事的管理層。"
