    "message": "在FAK和GZ的升降賽第五把的遊戲內容明顯原本FAK佔據優勢，卻因網路和伺服器原因導致比賽暫停，比賽陸續打打停停，到最後重賽卻單方面要求選手重新BP選角，而非使用原本BP陣容去做重賽，比賽結束後也未有明確的公告或規則說明，在此嚴正抗議，希望官方能夠出來說明，並提出合理合規的理由使第五把的重賽重新選角是合理的，否則有失比賽公平性以及戰隊及選手Riot官方的信任。"
