    "regionLabel": "台灣",
    "organization": "XD",
    "message": "把LCP 負責人員產品經理總監全都請他們離開，他們對賽區和選手的危害與負面效果已經遠超他們應該盡的責任與義務，賽制各種亂排很多沒必要的賽程擠在一起之後一打玩又很多空窗期，與其他賽區的賽程來比簡直是災難，，還有像是LCP去年線下的冠軍賽更是各種問題，不論是現場收音打光網路環境溫度沒一個是好的，為什麼選手和特地來的觀眾和主播要因為無能的管理層受這些委屈？還有像近期升降賽fak vs gz 先不說這個比賽打玩並不會影響一級聯賽的資格也沒有下一輪，意義不明，在這過程中只能用大型車禍現場形容，在選手打到一半大約二十分鐘，已經有一隊拿了三條的龍了，但在這之後卻是漫長的暫停，據主播說是因為現場ping 值過高，到底為什麼比賽會出現這種低級失誤啊，連區域網路都沒設定嗎，現場太多人用網路完全不是正當的理由，而且還因為暫停過久，兩邊選手都出現了金錢變多的bug，因此在漫長等待的暫停過後主辦單位重賽，非常的離譜，但更離譜的是據選手所稱他們從被通知到決定是否要照原本選角重賽只有10分鐘能決定，教練還被禁止參與討論，結果決定一樣選角後又說不行，兩邊選禁角都不一樣真的強烈建議嚴查相關賽事主辦人員是否從中得利太誇張"
