    "regionKey": "TW",
    "regionLabel": "台灣",
    "message": "1. 公開 2027 升降賽 FAK vs. GZ 第五局比賽違反競賽規章與強制重選角的完整調查報告，並向受影響戰隊與選手正式道歉。\n\n2. 全面評估新加坡管理團隊的適任性並追究相關人事責任，停止將戰隊自費經營的成果挪用為官方公關說詞。\n\n3. 恢復合理的比賽轉播時段與五戰三勝制場次比例，正視收視率雪崩與競技強度下滑的問題。\n\n4. 停止朝令夕改的賽區政策，維持制度中長期穩定，並恢復與中文等各語系社群的常態溝通管道。\n\n5. 捨棄空泛的公關畫餅，將有限預算務實投入在比賽伺服器、場館硬體、基礎轉播品質與裁判專業訓練上。\n\n6. 重新提供次級聯賽與草根社群賽事基本的官方轉播支援、獎金補助以及合理的二軍晉升空間。"
