    "rawRegion": "台灣",
    "regionKey": "TW",
    "regionLabel": "台灣",
    "message": "解釋一下這次FAK vs GZ到升降賽第五局吧！\n叫選手重做一個新的BP完全是在扯蛋，結合你們場地辦在越南，前不久還因為假賽事件而大幅開除選手的地方，很難不聯想到是主辦方的人員勾結了開賭盤的莊家，為了賭盤勝利，而去操作第五局這一連串荒謬至極的動作。\n如果主辦方無法解釋，或者還是用不耐煩的語氣想要搪塞過去，那我相信你們再也不會有人支持你們了。"
