    "rawRegion": "台灣",
    "regionKey": "TW",
    "regionLabel": "台灣",
    "message": "希望可以針對LCP賽區做更多的規劃，完善的次級環境，還有不要一直更改賽制，上賽季的瑞士制真的很爛，隊伍已經夠少了，而且是賽區內的比賽為什麼要套用像世界賽一樣的短期賽制真的很不合理，導致一些隊伍如果前面狀態不好連輸幾把就賽季結束了，這個真的很不合理，麻煩增加對於賽區內的補助或一些獎勵措施讓當地企業願意投入聯賽或隊伍，而不是一直畫大餅說要改些什麼但最後什麼都沒有，投入更多資源才能讓其他賽區不在只是中韓賽區的陪練，國際賽也才會更有觀賞性，職業聯賽才會長久"
