    "rawRegion": "台灣",
    "regionKey": "TW",
    "regionLabel": "台灣",
    "organization": "對lcp失望的觀眾",
    "message": "從GPL一路看到LMS再來的PCS跟現在的LCP，曾經的崛起到中期的短暫輝煌最後的奄奄一息，這一切都是你們造成的，你們不是沒有觀眾，在最興盛的時期我們甚至會到現場看比賽去支支持，但現在呢？戰隊留不住，人材留不住，賽區說改就改，配套完全沒有，明明在鼎盛時期好好經營就可以避免很多問題，但現在說提升到了5大賽區之一，你們自己信嗎？整合了這麼多地方，越南 日本賽區的觀眾有比較多人觀看嗎？收視率有增加嗎？更別說本地的觀看了，要不是去年還有psg咖薩 媽寶等老一輩和cfo的未來可期的唯一希望,，比賽根本沒人看，請你們好好經營，給予我們賽區基本的尊重"
