    "message": "LCP或許比不上LCK、LPL這些頂尖賽區，但展現出的熱情我相信是不比其他賽區差的，甚至在前一次的世界賽還擊敗了各強隊進入到了八強，這樣的表現我相信對於看比賽的觀眾來說是很振奮人心的，這種不確定因素也是我認為競技遊戲不可或缺的。但實際上我們賽區接受的待遇是什麼？缺薪、比賽設備差勁甚至還有比賽不公正的狀況，打到一半爆ping要重BP是正常比賽會有的狀況嗎？我們不是陪打的，也不是來湊數的，我們也是熱愛這遊戲，想要在世界的舞台上做出最好的表現，希望riot可以正視CLP賽區的問題。"
